<?php if($edit): ?><div class="row g-4 mb-4"><div class="col-xl-5"><section class="admin-card"><h2><?= e($edit['name']) ?> · Yetkiler</h2><form method="post" action="<?= e(url('admin/operations/permissions')) ?>"><?= App\Core\Csrf::field() ?><input type="hidden" name="employee_id" value="<?= (int)$edit['id'] ?>"><?php foreach(['can_confirm'=>'Randevu onaylayabilir','can_complete'=>'Süresi biten onaylı işlemi tamamlayabilir','can_request_cancel'=>'İptal talebi oluşturabilir']as$key=>$label): ?><label class="check-label"><input type="checkbox" name="<?= e($key) ?>" value="1" <?= $permissions[$key]?'checked':'' ?>><?= e($label) ?></label><?php endforeach ?><p class="muted">Çalışan doğrudan randevu iptal edemez; karar yöneticidedir.</p><button class="btn btn-outline-dark" type="submit">Yetkileri kaydet</button></form><hr><h3>Çalışma saatleri</h3><?php foreach($hours as$h): ?><p><?= e($dayNames[(int)$h['weekday']].' '.substr($h['start_time'],0,5).'–'.substr($h['end_time'],0,5)) ?></p><?php endforeach ?><a href="<?= e(url('admin/employees?id='.$edit['id'])) ?>">Çalışma saatlerini / hizmet atamalarını düzenle →</a></section></div><div class="col-xl-7"><section class="admin-card"><h2>Haftalık molalar</h2><form method="post" action="<?= e(url('admin/operations/breaks/add')) ?>" class="admin-form"><?= App\Core\Csrf::field() ?><input type="hidden" name="employee_id" value="<?= (int)$edit['id'] ?>"><label for="break-day">Gün</label><select class="form-select" id="break-day" name="weekday"><?php foreach($dayNames as$key=>$label): ?><option value="<?= $key ?>"><?= e($label) ?></option><?php endforeach ?></select><div class="row g-3"><div class="col-sm-6"><label for="break-start">Mola başlangıcı</label><input class="form-control" id="break-start" name="start_time" type="time" required></div><div class="col-sm-6"><label for="break-end">Mola bitişi</label><input class="form-control" id="break-end" name="end_time" type="time" required></div></div><label for="break-reason">Açıklama</label><input class="form-control" id="break-reason" name="reason" maxlength="120" required><p class="muted">Mola çalışma aralığı içinde olmalı; mevcut aktif randevularla çakışan mola eklenemez.</p><button class="btn btn-outline-dark" type="submit">Mola ekle</button></form><?php foreach($breaks as$b): ?><article class="leave-card"><strong><?= e($dayNames[(int)$b['weekday']].' '.substr($b['start_time'],0,5).'–'.substr($b['end_time'],0,5)) ?></strong><p><?= e($b['reason']) ?></p><form method="post" action="<?= e(url('admin/operations/breaks/remove')) ?>" data-confirm="Bu mola kaldırılsın mı?"><?= App\Core\Csrf::field() ?><input type="hidden" name="id" value="<?= (int)$b['id'] ?>"><button class="btn btn-sm btn-outline-danger" type="submit">Molayı kaldır</button></form></article><?php endforeach ?></section></div></div><?php else: ?><p class="muted">Yetkileri ve molaları düzenlemek için yukarıdan bir çalışan seçin.</p><?php endif ?>
<section class="admin-card mb-4"><h2>İzin talepleri</h2><?php if(!$leaveRequests): ?><p class="empty-state">Bu filtrede izin talebi yok.</p><?php endif ?><?php foreach($leaveRequests as$q): ?><article class="operation-request"><div class="section-heading"><h3>#<?= (int)$q['id'] ?> · <?= e($q['name']) ?></h3><span class="status-pill"><?= e($requestLabels[$q['status']]) ?></span></div><p><?= e(date('d.m.Y H:i',strtotime($q['start_at'])).' – '.date('d.m.Y H:i',strtotime($q['end_at']))) ?></p><p class="text-break"><?= e($q['reason']) ?></p><?php if($q['conflicts']): ?><div class="alert alert-warning"><strong>Çakışan randevular — izin onaylanamaz.</strong><p>Önce müşteriyle iletişime geçerek yönetici randevu ekranında açık bir çözüm uygulayın. Randevular otomatik iptal edilmez. Çözüm sonrası talebi tekrar değerlendirin.</p><ul><?php foreach($q['conflicts']as$a): ?><li>#<?= (int)$a['id'] ?> · <?= e($a['customer_name'].' · '.$a['service_name'].' · '.date('d.m H:i',strtotime($a['start_at']))) ?> <a href="<?= e(url('admin/appointments?date='.substr($a['start_at'],0,10))) ?>">Randevuyu çözümle</a></li><?php endforeach ?></ul></div><?php endif ?><?php if($q['status']==='pending'): ?><form method="post" action="<?= e(url('admin/operations/leaves/review')) ?>" class="admin-form"><?= App\Core\Csrf::field() ?><input type="hidden" name="id" value="<?= (int)$q['id'] ?>"><label for="leave-response-<?= (int)$q['id'] ?>">Değerlendirme notu (ret için zorunlu)</label><textarea class="form-control" id="leave-response-<?= (int)$q['id'] ?>" name="response" maxlength="1000" rows="2"></textarea><div class="wizard-actions"><button class="btn btn-lumera" name="decision" value="approved" type="submit" <?= $q['conflicts']?'disabled':'' ?>>İzni onayla</button><button class="btn btn-outline-danger" name="decision" value="rejected" type="submit">Talebi reddet</button></div></form><?php else: ?><p><?= e($q['response']??'') ?></p><small><?= e($q['reviewed_at']??'') ?></small><?php if($q['status']==='approved'&&!$q['approved_leave_id']): ?><p class="muted">Takvim izni sonradan kaldırılmış; talep geçmişi korunur.</p><?php endif ?><?php endif ?></article><?php endforeach ?></section>
<section class="admin-card mb-4"><h2>Randevu iptal talepleri</h2><?php if(!$cancelRequests): ?><p class="empty-state">Bu filtrede iptal talebi yok.</p><?php endif ?><?php foreach($cancelRequests as$q): ?><article class="operation-request"><div class="section-heading"><h3>Randevu #<?= (int)$q['appointment_id'] ?> · <?= e($q['employee_name']) ?></h3><span class="status-pill"><?= e($requestLabels[$q['status']]) ?></span></div><p><?= e($q['customer_name'].' · '.$q['service_name'].' · '.date('d.m.Y H:i',strtotime($q['start_at']))) ?></p><p><?= e($q['reason']) ?></p><p>Randevu durumu: <?= e($statusLabels[$q['appointment_status']]) ?></p><?php if($q['status']==='pending'): ?><form method="post" action="<?= e(url('admin/operations/cancellations/review')) ?>" class="admin-form"><?= App\Core\Csrf::field() ?><input type="hidden" name="id" value="<?= (int)$q['id'] ?>"><label for="cancel-response-<?= (int)$q['id'] ?>">Değerlendirme notu (ret için zorunlu)</label><textarea class="form-control" id="cancel-response-<?= (int)$q['id'] ?>" name="response" maxlength="1000" rows="2"></textarea><div class="wizard-actions"><button class="btn btn-lumera" name="decision" value="approved" type="submit" <?= in_array($q['appointment_status'],['pending','confirmed'],true)?'':'disabled' ?>>İptali onayla</button><button class="btn btn-outline-danger" name="decision" value="rejected" type="submit">Talebi reddet</button></div></form><?php else: ?><p><?= e($q['response']??'') ?></p><?php endif ?></article><?php endforeach ?></section>
